CREATE TABLE IF NOT EXISTS channels (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, data json NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS credentials (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, channel_id varchar(191) COLLATE utf8mb4_bin NOT NULL, data json NOT NULL, secret text NOT NULL, INDEX credentials_channel_idx(channel_id), FOREIGN KEY(channel_id) REFERENCES channels(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS settings (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, data json NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS api_keys (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, token_hash varchar(191) COLLATE utf8mb4_bin NOT NULL UNIQUE, data json NOT NULL, used bigint NOT NULL DEFAULT 0 CHECK (used >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS profile_usage (key_id varchar(191) COLLATE utf8mb4_bin NOT NULL, profile_id varchar(191) COLLATE utf8mb4_bin NOT NULL, used bigint NOT NULL DEFAULT 0 CHECK (used >= 0), PRIMARY KEY(key_id, profile_id), FOREIGN KEY(key_id) REFERENCES api_keys(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS tags (name varchar(191) COLLATE utf8mb4_bin PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS request_logs (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, created_at datetime(6) NOT NULL, channel_id varchar(191) COLLATE utf8mb4_bin, result varchar(32) NOT NULL, model varchar(256) NOT NULL, source varchar(32) NOT NULL, data json NOT NULL, INDEX request_logs_created_idx(created_at DESC), INDEX request_logs_channel_idx(channel_id,created_at DESC), INDEX request_logs_result_idx(result,created_at DESC)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS attempts (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, request_id varchar(191) COLLATE utf8mb4_bin NOT NULL, channel_id varchar(191) COLLATE utf8mb4_bin NOT NULL, started_at datetime(6) NOT NULL, data json NOT NULL, INDEX attempts_request_idx(request_id,started_at), INDEX attempts_channel_idx(channel_id,started_at DESC), FOREIGN KEY(request_id) REFERENCES request_logs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS events (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, created_at datetime(6) NOT NULL, data json NOT NULL, INDEX events_created_idx(created_at DESC)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS gateway_accounts (channel_id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, data json NOT NULL, secret text NOT NULL, FOREIGN KEY(channel_id) REFERENCES channels(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS gateway_state (id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, value text NOT NULL, expires_at datetime(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS channel_rate_limits (channel_id varchar(191) COLLATE utf8mb4_bin NOT NULL, minute bigint NOT NULL, requests bigint NOT NULL DEFAULT 0, tokens bigint NOT NULL DEFAULT 0, PRIMARY KEY(channel_id,minute), FOREIGN KEY(channel_id) REFERENCES channels(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS credential_balance_jobs (credential_id varchar(191) COLLATE utf8mb4_bin PRIMARY KEY, next_refresh_at bigint NOT NULL DEFAULT 0, lease_until bigint NOT NULL DEFAULT 0, INDEX credential_balance_jobs_due_idx(next_refresh_at,lease_until), FOREIGN KEY(credential_id) REFERENCES credentials(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
